/-- Bounded measurable observable estimators; clipping to `[0,1]` is loss reducing. -/
def ObservableEstimator (T : Nat) : Type :=
  {est : RawEstimator T //
    (∀ b e w, est b e w ∈ Set.Icc (0 : ℝ) 1) ∧
    (∀ b e, Measurable (est b e))}

