lemma sequentialIgnorability_supported_action {T : Nat}
    (M : RawPomdpExperiment T 2 2) (hI : SequentialIgnorability M) (t : Fin T) :
    ∀ᵐ tau ∂M.law, M.b (curState t tau).1 (actionAt t tau) ≠ 0

lemma pomdp_reward_mem_Icc_ae {T : Nat}
    (M : RawPomdpExperiment T 2 2) (hK : PomdpKernelLaw M) (t : Fin T) :
    ∀ᵐ tau ∂M.law, rewardAt t tau ∈ Set.Icc (0 : ℝ) 1

lemma pomdp_reward_integrable {T : Nat}
    (M : RawPomdpExperiment T 2 2) (hK : PomdpKernelLaw M) (t : Fin T) :
    Integrable (rewardAt t) M.law

lemma gridCandidates_row {M : Nat} {alpha : ℝ} {c : GridCode M}
    (hc : c ∈ gridCandidates M alpha) (i : Fin 4) :
    IsGridRow M (c.2.1 i)

/-- A simplex grid row is a nonnegative integer tuple summing to `M`. -/
def IsGridRow (M : Nat) (u : Fin 4 → Fin (M + 1)) : Prop :=
  ∑ i, (u i).val = M

gridDobrushin_perturbation.statement:
lemma gridDobrushin_perturbation (P R : Matrix (Fin 4) (Fin 4) ℝ) {ε : ℝ}
    (hPR : ∀ i, (1 / 2 : ℝ) * ∑ j, |P i j - R i j| ≤ ε) :
    gridDobrushin R ≤ gridDobrushin P + 2 * ε

