def finitePomdpView {T : Nat} (M : RawPomdpExperiment T 2 2) :
    CausalSmith.Stat.PomdpLatentOverlapMinimax.RawPomdpExperiment T 2 2 :=
  { K := M.K, b := M.b, e := M.e, init := M.init,
    law := M.law, law_isProbability := M.law_isProbability }

